package app.xiaohe.tests;
import android.content.Context;import app.xiaohe.assistant.*;import org.json.*;import java.util.*;import java.io.*;
public final class LargeRowSmoke {
  private static void ok(boolean yes,String text){if(!yes)throw new AssertionError(text);}
  public static void run(Store db,Context c)throws Exception {
    StringBuilder content=new StringBuilder();for(int i=0;i<110000;i++)content.append("完整长文 汉字🙂 C++ 2.5 / 25\n");String text=content.toString(),fid=UUID.randomUUID().toString();File path=db.filePath(fid);try(Writer writer=new OutputStreamWriter(new FileOutputStream(path),"UTF-8")){writer.write(text);}JSONObject file=new JSONObject().put("id",fid).put("created",System.currentTimeMillis()).put("name","大行原始全文.txt").put("mime","text/plain").put("size",path.length()).put("sha256",MediaProcessor.hash(path)).put("text",text);ok(file.toString().getBytes("UTF-8").length>2*1024*1024,"Fixture must exceed default CursorWindow");db.put("files",file);
    JSONObject m=db.message("user",text,new JSONArray().put(fid),UUID.randomUUID().toString());JSONObject r=new JSONObject().put("id",UUID.randomUUID().toString()).put("created",System.currentTimeMillis()).put("sourceId",m.getString("id")).put("type","learning").put("kind","note").put("status","active").put("title","大行完整存储回归").put("content",text).put("files",new JSONArray().put(fid)).put("tags",new JSONArray().put("大行回归"));db.put("memories",r);
    ok(db.one("files",fid).getString("text").equals(text),"Large file metadata cannot truncate Unicode/emoji");ok(db.one("messages",m.getString("id")).getString("content").equals(text),"Large original message reads completely");ok(db.one("memories",r.getString("id")).getString("content").equals(text),"Large memory reads completely");ok(new MemoryLedger(db).history(r.getString("id")).getJSONObject(0).getJSONObject("snapshot").getString("content").equals(text),"Large immutable snapshot reads completely");ok(new MemoryLedger(db).page(new JSONObject().put("status","all").put("query","大行完整存储回归")).getJSONArray("rows").length()>0,"Joined/indexed JSON projection supports large rows");
    JSONObject boot=db.bootstrap();boolean found=false;for(int i=0;i<boot.getJSONArray("files").length();i++){JSONObject f=boot.getJSONArray("files").getJSONObject(i);if(f.optString("id").equals(fid)){found=true;ok(!f.has("text"),"Bootstrap should project material metadata without full extracted text");}}ok(found,"Large file retained in metadata library");
    File archive=new File(c.getCacheDir(),"large-roundtrip.zip");try(OutputStream out=new FileOutputStream(archive)){new Backup(c).exportTo(out);}try(InputStream in=new FileInputStream(archive)){ok(new Backup(c).importFrom(in).optInt("added")==0,"Large backup re-import has no duplicates");}db.delete("memories",r.getString("id"));try(InputStream in=new FileInputStream(archive)){ok(new Backup(c).importFrom(in).optInt("added")==1,"Large missing record restored");}ok(db.one("memories",r.getString("id")).getString("content").equals(text),"Restored large body complete");ok(MediaProcessor.hash(path).equals(file.getString("sha256")),"Original bytes retain SHA-256 after restore");archive.delete();
  }
}
